"""Small standard-library implementation of the Task template expressions used in commands."""
import re

_TOKEN = re.compile(r'{{\s*(.*?)\s*}}', re.S)


def _resolve(expr, ctx):
    expr = expr.strip()
    if not expr:
        return ''
    if expr.startswith('"') and expr.endswith('"'):
        return expr[1:-1]
    if expr.startswith("'") and expr.endswith("'"):
        return expr[1:-1]
    if expr in ('true', 'false'):
        return expr == 'true'
    if expr == 'nil' or expr == 'null':
        return None
    if expr.startswith('.'):
        parts = expr[1:].split('.')
        value = ctx
        for part in parts:
            if isinstance(value, dict):
                value = value.get(part, '')
            elif isinstance(value, (list, tuple)) and part.isdigit():
                try: value = value[int(part)]
                except IndexError: return ''
            else:
                value = getattr(value, part, '')
        return value
    # Go-template's common boolean/comparison functions. Arguments are parsed
    # with a tokenizer that preserves quoted strings and nested expressions.
    m = re.match(r'^(eq|ne|lt|le|gt|ge|and|or|not)\s+(.*)$', expr, re.S)
    if m:
        op, rest = m.groups()
        args = _arguments(rest, ctx)
        if op == 'eq': return bool(args) and all(x == args[0] for x in args[1:])
        if op == 'ne': return bool(args) and all(x != args[0] for x in args[1:])
        if op in ('lt','le','gt','ge') and len(args) >= 2:
            try: return {'lt':args[0]<args[1], 'le':args[0]<=args[1], 'gt':args[0]>args[1], 'ge':args[0]>=args[1]}[op]
            except TypeError: return False
        if op == 'and': return all(args)
        if op == 'or': return next((a for a in args if a), args[-1] if args else '')
        if op == 'not': return not (args[0] if args else False)
    return ctx.get(expr, '') if isinstance(ctx, dict) else ''


def _arguments(text, ctx):
    return [_resolve(tok, ctx) for tok in re.findall(r'"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\'|[^\s]+', text)]


def render(value, context):
    """Expand Task-style ``{{.VAR}}`` and common boolean template expressions."""
    if not isinstance(value, str):
        return value
    return _TOKEN.sub(lambda m: str(_resolve(m.group(1), context) if _resolve(m.group(1), context) is not None else ''), value)

