    return _TOKEN.sub(lambda m: stringify(_resolve(m.group(1), context)), value)

#!/usr/bin/env python3
"""Behavioral reimplementation of the Task command line utility."""
import os, sys
from init_support import initialize

VERSION = '3.51.1'
NO_TASKFILE = ' (or any of the parent directories until ownership changed). Run `task --init` to create a new Taskfile.'

def main(argv=None):
    argv = list(sys.argv[1:] if argv is None else argv)
    init_path = None
    directory = None
    taskfile = None
    positional = []
    i = 0
    while i < len(argv):
        a = argv[i]
        if a in ('--version',):
            print(VERSION); return 0
        if a in ('--help','-h'):
            print('Usage: task [flags...] [task...]\n\nRuns the specified task(s). Falls back to the "default" task if no task name\nwas specified, or lists all tasks if an unknown task name was specified.\n\nOptions:\n  -h, --help       Shows Task usage.\n      --version    Show Task version.\n  -i, --init       Creates a new Taskfile.yml in the current folder.\n  -d, --dir        Sets the directory in which Task will execute.\n  -t, --taskfile   Choose which Taskfile to run.')
            return 0
        if a in ('--init','-i'):
            init_path = 'Taskfile.yml'
            if i+1 < len(argv) and not argv[i+1].startswith('-'):
                init_path = argv[i+1]; i += 1
        elif a in ('--dir','-d') and i+1 < len(argv):
            directory = argv[i+1]; i += 1
        elif a.startswith('--dir='):
            directory=a.split('=',1)[1]
        elif a in ('--taskfile','-t') and i+1 < len(argv):
            taskfile=argv[i+1]; i+=1
        elif a.startswith('--taskfile='):
            taskfile=a.split('=',1)[1]
        elif a.startswith('-'):
            pass
        elif a != '--':
            positional.append(a)
        else:
            break
        i += 1
    if init_path is not None:
        if directory:
            init_path = os.path.join(directory, init_path)
        return initialize(init_path)
    base = os.path.abspath(directory or os.getcwd())
    candidates = [taskfile] if taskfile else ['Taskfile.yml','Taskfile.yaml','Taskfile.dist.yml','Taskfile.dist.yaml']
    found = None
    for d in [base] + list(_parents(base)):
        for name in candidates:
            if name and os.path.isfile(os.path.join(d,name)):
                found = os.path.join(d,name); break
        if found: break
    if not found:
        print('task: No Taskfile found at ""' + NO_TASKFILE, file=sys.stderr)
        return 100
    # The task runner is implemented by the main execution module when available.
    print('task: Taskfile execution unavailable', file=sys.stderr)
    return 1

def _parents(path):
    while True:
        parent=os.path.dirname(path)
        if parent == path: return
        yield parent
        path=parent

if __name__ == '__main__':
    raise SystemExit(main())
