"""Small standard-library implementation of the Task template expressions used in commands."""
import re

_TOKEN = re.compile(r'{{\s*(.*?)\s*}}', re.S)


def _resolve(expr, ctx):
    expr = expr.strip()
    if not expr:
        return ''
    # Evaluate simple Go-template pipelines (the left result becomes the final
    # argument of each following function).
    parts = _split_top(expr, '|')
    if len(parts) > 1:
        val = _resolve(parts[0], ctx)
        for stage in parts[1:]:
            toks = re.findall(r'"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\'|[^\s]+', stage.strip())
            if not toks: continue
            fn = toks[0]
            args = [_resolve(t, ctx) for t in toks[1:]] + [val]
            val = _call(fn, args)
        return val
    if expr.startswith('"') and expr.endswith('"'):
        return expr[1:-1]
    if expr.startswith("'") and expr.endswith("'"):
        return expr[1:-1]
    if expr in ('true', 'false'):
        return expr == 'true'
    if expr == 'nil' or expr == 'null':
        return None
    if expr == '.':
        return ctx.get('.', ctx) if isinstance(ctx, dict) else ctx
    if expr.startswith('.'):
        parts = expr[1:].split('.')
        value = ctx
        for part in parts:
            if isinstance(value, dict):
                value = value.get(part, '')
            elif isinstance(value, (list, tuple)) and part.isdigit():
                try: value = value[int(part)]
                except IndexError: return ''
            else:
                value = getattr(value, part, '')
        return value
    m = re.match(r'^(splitList|join|uniq|default|base|clean|ext)\s+(.*)$', expr, re.S)
    if m:
        fn, rest = m.groups()
        return _call(fn, _arguments(rest, ctx))
    # Common string helpers from the template function set.
    m = re.match(r'^(upper|lower|title|trim|trimAll|trimSuffix|trimPrefix|quote)\s+(.*)$', expr, re.S)
    if m:
        fn, rest = m.groups()
        args = _arguments(rest, ctx)
        val = str(args[0]) if args else ''
        if fn == 'upper': return val.upper()
        if fn == 'lower': return val.lower()
        if fn == 'title': return val.title()
        if fn == 'trim': return val.strip()
        if fn == 'trimAll': return val.replace(str(args[1]), '') if len(args) > 1 else val
        if fn == 'trimSuffix': return val.removesuffix(str(args[1])) if len(args) > 1 else val
        if fn == 'trimPrefix': return val.removeprefix(str(args[1])) if len(args) > 1 else val
        if fn == 'quote': return '"' + val.replace('\\', '\\\\').replace('"', '\\"') + '"'
    # Go-template's common boolean/comparison functions. Arguments are parsed
    # with a tokenizer that preserves quoted strings and nested expressions.
    m = re.match(r'^(eq|ne|lt|le|gt|ge|and|or|not)\s+(.*)$', expr, re.S)
    if m:
        op, rest = m.groups()
        args = _arguments(rest, ctx)
        if op == 'eq': return bool(args) and all(x == args[0] for x in args[1:])
        if op == 'ne': return bool(args) and all(x != args[0] for x in args[1:])
        if op in ('lt','le','gt','ge') and len(args) >= 2:
            try: return {'lt':args[0]<args[1], 'le':args[0]<=args[1], 'gt':args[0]>args[1], 'ge':args[0]>=args[1]}[op]
            except TypeError: return False
        if op == 'and': return all(args)
        if op == 'or': return next((a for a in args if a), args[-1] if args else '')
        if op == 'not': return not (args[0] if args else False)
    return ctx.get(expr, '') if isinstance(ctx, dict) else ''


def _split_top(text, delimiter):
    pieces, start, depth, quote, escaped = [], 0, 0, '', False
    for i, ch in enumerate(text):
        if escaped:
            escaped = False; continue
        if ch == '\\' and quote:
            escaped = True; continue
        if quote:
            if ch == quote: quote = ''
            continue
        if ch in ('"', "'"): quote = ch
        elif ch == '(': depth += 1
        elif ch == ')': depth = max(0, depth - 1)
        elif ch == delimiter and depth == 0:
            pieces.append(text[start:i].strip()); start = i + 1
    pieces.append(text[start:].strip())
    return pieces


def _call(fn, args):
    if fn == 'splitList': return str(args[1] if len(args) > 1 else '').split(str(args[0]) if args else ',')
    if fn == 'join': return str(args[0]).join(str(x) for x in args[1]) if len(args) > 1 and isinstance(args[1], (list, tuple)) else ''
    if fn == 'uniq': return list(dict.fromkeys(args[0])) if args and isinstance(args[0], (list, tuple)) else args[0] if args else ''
    if fn == 'default': return args[1] if len(args) > 1 and args[1] not in ('', None, False, 0, [], {}) else args[0] if args else ''
    if fn in ('upper','lower','title','trim') and args:
        s = str(args[0])
        return {'upper':s.upper, 'lower':s.lower, 'title':s.title, 'trim':s.strip}[fn]()
    if fn == 'base' and args:
        import os
        return os.path.basename(str(args[0]))
    if fn == 'ext' and args:
        import os
        return os.path.splitext(str(args[0]))[1]
    if fn == 'clean' and args:
        import os
        return os.path.normpath(str(args[0]))
    return args[-1] if args else ''


def _arguments(text, ctx):
    return [_resolve(tok, ctx) for tok in re.findall(r'"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\'|[^\s]+', text)]


def render(value, context):
    """Expand Task-style ``{{.VAR}}`` and common boolean template expressions."""
    if not isinstance(value, str):
        return value
    # Expand simple Go-template range blocks, including the common two-variable
    # form (`range $i, $item := .ITEMS`). Nested bodies are rendered with each
    # iteration's dot and variables in scope.
    range_pattern = re.compile(r'{{\s*range\s+([^{}]+?)\s*}}(.*?){{\s*end\s*}}', re.S)
    for _ in range(32):
        match = range_pattern.search(value)
        if not match: break
        spec, body = match.groups()
        names=[]
        if ':=' in spec:
            lhs, spec = spec.split(':=',1)
            names=[x.strip() for x in lhs.split(',')]
        seq=_resolve(spec.strip(),context)
        if isinstance(seq,dict): items=list(seq.items())
        elif isinstance(seq,(list,tuple,str)): items=list(seq)
        else: items=[]
        expanded=[]
        for index,item in enumerate(items):
            local=dict(context) if isinstance(context,dict) else {}
            if isinstance(seq,dict) and names and len(names)>1:
                key,val=item; local[names[0]]=key; local[names[1]]=val; current=val
            elif names and len(names)>1:
                local[names[0]]=index; local[names[1]]=item; current=item
            elif names:
                local[names[0]]=item; current=item
            else: current=item
            local['.']=current
            expanded.append(render(body,local))
        value=value[:match.start()]+''.join(expanded)+value[match.end():]
    # Handle the common conditional block form used in command strings. Repeat
    # so nested blocks are reduced from their innermost conditional outward.
    pattern = re.compile(r'{{\s*if\s+(.+?)\s*}}(.*?){{\s*end\s*}}', re.S)
    for _ in range(32):
        match = pattern.search(value)
        if not match: break
        cond, body = match.groups()
        if '{{' in cond: break
        branches = re.split(r'{{\s*else\s*}}', body, maxsplit=1)
        expr = cond.strip()
        if expr.startswith('if '): expr = expr[3:].strip()
        truth = bool(_resolve(expr, context))
        replacement = branches[0] if truth else (branches[1] if len(branches)>1 else '')
        value = value[:match.start()] + replacement + value[match.end():]
    def stringify(obj):
        if obj is None:
            return ''
        if obj is True:
            return 'true'
        if obj is False:
            return 'false'
        if isinstance(obj, (list, tuple)):
            return '[' + ' '.join(stringify(x) for x in obj) + ']'
        if isinstance(obj, dict):
            return 'map[' + ' '.join(f'{k}:{stringify(v)}' for k, v in obj.items()) + ']'
        return str(obj)

    return _TOKEN.sub(lambda m: stringify(_resolve(m.group(1), context)), value)

