        spec=opener.group().removeprefix('{{').removesuffix('}}').strip()[5:].strip()
        branches=re.split(r'{{\s*else\s*}}',body,maxsplit=1)
        loop_body=branches[0]
        names=[]
        if ':=' in spec:
            lhs, spec = spec.split(':=',1)
            names=[x.strip() for x in lhs.split(',')]
        seq=_resolve(spec.strip(),context)
        if isinstance(seq,dict): items=list(seq.items())
        elif isinstance(seq,(list,tuple,str)): items=list(seq)
        else: items=[]
        expanded=[]
        for index,item in enumerate(items):
            local=dict(context) if isinstance(context,dict) else {}
            if isinstance(seq,dict) and names and len(names)>1:
                key,val=item; local[names[0]]=key; local[names[1]]=val; current=val
            elif names and len(names)>1:
                local[names[0]]=index; local[names[1]]=item; current=item
            elif names:
                local[names[0]]=item; current=item
            else: current=item
            local['.']=current
            rendered=render(loop_body,local)
            if _BREAK in rendered:
                expanded.append(rendered.split(_BREAK,1)[0])
                break
            expanded.append(rendered)
        replacement=''.join(expanded)
        if not items and len(branches)>1:replacement=render(branches[1],context)
        value=value[:opener.start()]+replacement+value[closer.end():]
    # Handle the common conditional block form used in command strings. Repeat
    # so nested blocks are reduced from their innermost conditional outward.
    for _ in range(32):
        block=_find_block(value,'if')
        if not block: break
        opener,body,closer=block
        cond=opener.group().removeprefix('{{').removesuffix('}}').strip()[2:].strip()
        if '{{' in cond: break
        branches = re.split(r'{{\s*else\s*}}', body, maxsplit=1)
        expr = cond.strip()
        if expr.startswith('if '): expr = expr[3:].strip()
        truth = bool(_resolve(expr, context))
        replacement = branches[0] if truth else (branches[1] if len(branches)>1 else '')
        value = value[:opener.start()] + replacement + value[closer.end():]
    def stringify(obj):
        if obj == _BREAK:
            return _BREAK
        if obj is None:
            return ''
        if obj is True:
            return 'true'
        if obj is False:
            return 'false'
        if isinstance(obj, (list, tuple)):
            return '[' + ' '.join(stringify(x) for x in obj) + ']'
        if isinstance(obj, dict):
            return 'map[' + ' '.join(f'{k}:{stringify(v)}' for k, v in obj.items()) + ']'
        return str(obj)

    return _TOKEN.sub(lambda m: stringify(_resolve(m.group(1), context)), value)

